import { writeTrace } from './logging/trace.js';
import { mockEvaluation } from './mock.js';
import { applyPolicy } from './policy.js';
import { inspectRepo } from './repo/inspect.js';
import type {
  Action,
  AgentAssessment,
  AgentState,
  EvaluationResult,
  PolicyDecision,
  RepoSnapshot,
} from './types.js';

export const EXIT_CODES = {
  success: 0,
  operationalError: 1,
  usageError: 2,
} as const;

export type CliOptions = {
  repoPath: string;
  task: string;
  mock: boolean;
  noTrace: boolean;
  json: boolean;
};

export type CliCommand =
  | { kind: 'help' }
  | { kind: 'version' }
  | { kind: 'run'; options: CliOptions };

export type DecisionOutput = {
  schemaVersion: 1;
  status: 'unexecuted';
  mode: 'mock' | 'live';
  repo: RepoSnapshot;
  task: string;
  assessment: AgentAssessment;
  policy: PolicyDecision;
  model: string;
  latencyMs: number;
  tracePath?: string;
};

type ErrorOutput = {
  schemaVersion: 1;
  status: 'error';
  error: {
    kind: 'usage' | 'operational';
    message: string;
  };
  exitCode: number;
};

export class CliUsageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CliUsageError';
  }
}

export function usage(): string {
  return `jev-agent <repo-path> <task> [--mock] [--no-trace] [--json]

Options:
  --mock       Use the offline deterministic evaluation.
  --no-trace   Do not write a JSONL trace.
  --json       Write one machine-readable decision to stdout.
  --version    Print the installed package version.
  --help, -h   Print this help text.

Examples:
  pnpm dev -- . "Decide what to inspect first"
  pnpm dev -- ../my-app "Fix preview auth" --mock --json --no-trace

Environment:
  AI_GATEWAY_API_KEY   Vercel AI Gateway key
  ROUTER_MODEL         Defaults to typesafe-ai/jev

Exit codes:
  0  A decision, help text, or version was printed.
  1  An operational error prevented a decision.
  2  Invalid command-line usage.`;
}

function usageError(message: string): CliUsageError {
  return new CliUsageError(`${message}\n\n${usage()}`);
}

function taskFromPositionals(positionals: string[]): string {
  try {
    return requireBoundedTask(positionals.slice(1).join(' ').trim());
  } catch (error) {
    throw usageError(error instanceof Error ? error.message : String(error));
  }
}

function withoutNodeArgumentSeparator(argv: string[]): string[] {
  return argv[0] === '--' ? argv.slice(1) : argv;
}

export function parseArgs(argv: string[]): CliCommand {
  let mock = false;
  let noTrace = false;
  let json = false;
  let showHelp = false;
  let showVersion = false;
  let parseFlags = true;
  const positional: string[] = [];

  for (const arg of withoutNodeArgumentSeparator(argv)) {
    if (!parseFlags) {
      positional.push(arg);
      continue;
    }

    if (arg === '--') {
      parseFlags = false;
      continue;
    }

    switch (arg) {
      case '--mock':
        mock = true;
        break;
      case '--no-trace':
        noTrace = true;
        break;
      case '--json':
        json = true;
        break;
      case '--help':
      case '-h':
        showHelp = true;
        break;
      case '--version':
        showVersion = true;
        break;
      default:
        if (arg.startsWith('-')) {
          throw usageError(`Unknown option: ${arg}`);
        }
        positional.push(arg);
    }
  }

  if (showHelp || showVersion) {
    if (showHelp && showVersion) {
      throw usageError('Use either --help or --version, not both.');
    }
    if (mock || noTrace || json || positional.length > 0) {
      throw usageError('--help and --version cannot be combined with a decision request.');
    }
    return showHelp ? { kind: 'help' } : { kind: 'version' };
  }

  if (positional.length < 2) {
    throw usageError('Missing repository path or task.');
  }

  const repoPath = positional[0] ?? '';
  const task = taskFromPositionals(positional);
  return {
    kind: 'run',
    options: { repoPath, task, mock, noTrace, json },
  };
}

function percent(value: number): string {
  return `${Math.round(value * 100)}%`;
}

function printDistribution(probabilities: Partial<Record<Action, number>>): void {
  const entries = Object.entries(probabilities).sort(([, a], [, b]) => (b ?? 0) - (a ?? 0));
  for (const [action, probability] of entries) {
    console.log(`  ${action.padEnd(14)} ${percent(probability ?? 0).padStart(4)}`);
  }
}

function makeState(repo: RepoSnapshot, task: string): AgentState {
  return {
    task,
    iteration: 1,
    currentGoal: 'Choose the safest useful first action.',
    repo,
    filesRead: [],
    filesModified: [],
    observations: ['Initial repository snapshot collected.'],
    commandsRun: [],
    tests: { ran: false },
    failedApproaches: [],
    codexCalls: 0,
  };
}

export function createDecisionOutput(
  state: AgentState,
  evaluation: EvaluationResult,
  policy: PolicyDecision,
  mode: DecisionOutput['mode'],
  tracePath?: string,
): DecisionOutput {
  return {
    schemaVersion: 1,
    status: 'unexecuted',
    mode,
    repo: state.repo,
    task: state.task,
    assessment: evaluation.assessment,
    policy,
    model: evaluation.model,
    latencyMs: evaluation.latencyMs,
    ...(tracePath === undefined ? {} : { tracePath }),
  };
}

export async function runDecision(
  options: Omit<CliOptions, 'json'>,
  cwd: string = process.cwd(),
): Promise<DecisionOutput> {
  const repo = await inspectRepo(options.repoPath);
  const state = makeState(repo, options.task);
  const mode: DecisionOutput['mode'] = options.mock ? 'mock' : 'live';

  if (!options.mock) requireGatewayApiKey();
  const evaluation = options.mock ? mockEvaluation() : await evaluateAgentState(state);
  const policy = applyPolicy(state, evaluation.assessment);
  const tracePath = options.noTrace
    ? undefined
    : path.relative(cwd, await writeTrace(cwd, { state, evaluation, policy }));

  return createDecisionOutput(state, evaluation, policy, mode, tracePath);
}

function printHumanDecision(decision: DecisionOutput): void {
  const { assessment, policy } = decision;
  console.log('\nJev Orchestrator — decision-only milestone');
  console.log('Status: unexecuted decision (no tools or coding agents ran)\n');
  console.log(`Repo: ${decision.repo.root}`);
  console.log(`Task: ${decision.task}`);
  console.log(`Mode: ${decision.mode === 'mock' ? 'mock' : 'live Jev'}\n`);
  console.log(`Task complete       ${percent(assessment.taskComplete.probability)}`);
  console.log(`Needs information  ${percent(assessment.needsMoreInformation.probability)}`);
  console.log(`Needs testing      ${percent(assessment.needsTesting.probability)}`);
  console.log(`Stuck              ${percent(assessment.stuck.probability)}\n`);
  console.log('Next-action distribution');
  printDistribution(assessment.nextAction.probabilities);
  console.log(`\nJev requested: ${policy.requested}`);
  console.log(`Policy selected (unexecuted): ${policy.selected}${policy.override ? ' (override)' : ''}`);
  console.log(`Reason: ${policy.reason}`);
  console.log(`Latency: ${decision.latencyMs}ms`);
  if (decision.tracePath !== undefined) console.log(`Trace: ${decision.tracePath}`);
}

async function packageVersion(): Promise<string> {
  const manifest = await readFile(new URL('../package.json', import.meta.url), 'utf8');
  const parsed: unknown = JSON.parse(manifest);
  if (
    typeof parsed !== 'object' ||
    parsed === null ||
    !('version' in parsed) ||
    typeof parsed.version !== 'string'
  ) {
    throw new Error('Unable to read the package version.');
  }
  return parsed.version;
}

export function exitCodeFor(error: unknown): number {
  return error instanceof CliUsageError
    ? EXIT_CODES.usageError
    : EXIT_CODES.operationalError;
}

function errorOutput(error: unknown): ErrorOutput {
  const usage = error instanceof CliUsageError;
  return {
    schemaVersion: 1,
    status: 'error',
    error: {
      kind: usage ? 'usage' : 'operational',
      message: error instanceof Error ? error.message : String(error),
    },
    exitCode: exitCodeFor(error),
  };
}

function wantsJsonError(argv: string[]): boolean {
  let parseFlags = true;
  for (const arg of withoutNodeArgumentSeparator(argv)) {
    if (!parseFlags) continue;
    if (arg === '--') {
      parseFlags = false;
      continue;
    }
    if (arg === '--json') return true;
  }
  return false;
}

export async function main(argv: string[] = process.argv.slice(2)): Promise<void> {
  const command = parseArgs(argv);
  if (command.kind === 'help') {
    console.log(usage());
    return;
  }
  if (command.kind === 'version') {
    console.log(await packageVersion());
    return;
  }

  const decision = await runDecision(command.options);
  if (command.options.json) {
    console.log(JSON.stringify(decision));
    return;
  }
  printHumanDecision(decision);
}

function isDirectInvocation(): boolean {
  const entryPoint = process.argv[1];
  return entryPoint !== undefined && import.meta.url === pathToFileURL(path.resolve(entryPoint)).href;
}

if (isDirectInvocation()) {
  void main().catch((error: unknown) => {
    if (wantsJsonError(process.argv.slice(2))) {
      console.error(JSON.stringify(errorOutput(error)));
    } else {
      console.error(`\nError: ${error instanceof Error ? error.message : String(error)}`);
    }
    process.exitCode = exitCodeFor(error);
  });
}
import { describe, expect, it } from 'vitest';
import {
  CliUsageError,
  createDecisionOutput,
  EXIT_CODES,
  exitCodeFor,
  parseArgs,
} from './cli.js';
import { mockEvaluation } from './mock.js';
import type { AgentState, PolicyDecision } from './types.js';

const state: AgentState = {
  task: 'Inspect the repository',
  iteration: 1,
  currentGoal: 'Choose an action',
  repo: {
    root: '/repo',
    packageManager: 'pnpm',
    scripts: ['test'],
    validationScripts: ['test'],
    gitStatus: [],
    topLevelFiles: ['package.json'],
  },
  filesRead: [],
  filesModified: [],
  observations: [],
  commandsRun: [],
  tests: { ran: false },
  failedApproaches: [],
  codexCalls: 0,
};

const policy: PolicyDecision = {
  requested: 'SEARCH_REPO',
  selected: 'SEARCH_REPO',
  override: false,
  reason: 'Clear recommendation.',
};

describe('parseArgs', () => {
  it('parses known flags independently of positional argument order', () => {
    expect(parseArgs(['--mock', '/repo', '--json', 'Inspect', 'this', '--no-trace'])).toEqual({
      kind: 'run',
      options: {
        repoPath: '/repo',
        task: 'Inspect this',
        mock: true,
        noTrace: true,
        json: true,
      },
    });
  });

  it('ignores the Node argument separator added by pnpm dev', () => {
    expect(parseArgs(['--', '/repo', 'Inspect', '--mock', '--json'])).toEqual({
      kind: 'run',
      options: {
        repoPath: '/repo',
        task: 'Inspect',
        mock: true,
        noTrace: false,
        json: true,
      },
    });
  });

  it('treats arguments after -- as positional task text', () => {
    expect(parseArgs(['/repo', 'Investigate', '--', '--not-a-flag'])).toEqual({
      kind: 'run',
      options: {
        repoPath: '/repo',
        task: 'Investigate --not-a-flag',
        mock: false,
        noTrace: false,
        json: false,
      },
    });
  });

  it('returns help and version commands without a decision request', () => {
    expect(parseArgs(['--help'])).toEqual({ kind: 'help' });
    expect(parseArgs(['--version'])).toEqual({ kind: 'version' });
  });

  it('rejects unknown flags and incomplete decision requests', () => {
    expect(() => parseArgs(['/repo', 'Inspect', '--unsafe'])).toThrow(CliUsageError);
    expect(() => parseArgs(['/repo'])).toThrow(CliUsageError);
    expect(() => parseArgs(['--help', '--mock'])).toThrow(CliUsageError);
  });
});

describe('CLI output contract', () => {
  it('creates a bounded JSON decision with explicit unexecuted status', () => {
    const output = createDecisionOutput(state, mockEvaluation(), policy, 'mock', 'traces/run.jsonl');
    const serialized = JSON.parse(JSON.stringify(output)) as Record<string, unknown>;

    expect(serialized).toMatchObject({
      schemaVersion: 1,
      status: 'unexecuted',
      mode: 'mock',
      task: state.task,
      policy,
      tracePath: 'traces/run.jsonl',
    });
    expect(serialized).not.toHaveProperty('rawAnswers');
    expect(serialized).not.toHaveProperty('providerMetadata');
  });

  it('omits the trace path when tracing is disabled', () => {
    const output = createDecisionOutput(state, mockEvaluation(), policy, 'mock');

    expect(output).not.toHaveProperty('tracePath');
  });

  it('uses distinct usage and operational exit codes', () => {
    expect(exitCodeFor(new CliUsageError('Bad input'))).toBe(EXIT_CODES.usageError);
    expect(exitCodeFor(new Error('Gateway unavailable'))).toBe(EXIT_CODES.operationalError);
  });
});
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { main, runDecision } from './cli.js';
import { TraceWriteError } from './logging/trace.js';

const roots: string[] = [];

async function temporaryRepository(): Promise<string> {
  const root = await mkdtemp(path.join(os.tmpdir(), 'jev-cli-integration-'));
  roots.push(root);
  await writeFile(path.join(root, 'package.json'), JSON.stringify({
    name: 'fixture-repository',
    scripts: {
      test: 'vitest run',
      lint: 'eslint .',
      deploy: 'not-an-allowed-validation-script',
    },
  }));
  await writeFile(path.join(root, 'pnpm-lock.yaml'), 'lockfileVersion: 9');
  await writeFile(path.join(root, 'index.ts'), 'export const fixture = true;\n');
  return root;
}

afterEach(async () => {
  vi.restoreAllMocks();
  vi.unstubAllEnvs();
  await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
});

describe('offline CLI integration', () => {
  it('inspects a temporary repository and emits one JSON decision in mock mode', async () => {
    const root = await temporaryRepository();
    const log = vi.spyOn(console, 'log').mockImplementation(() => undefined);

    await main([root, 'Inspect the fixture repository', '--mock', '--no-trace', '--json']);

    expect(log).toHaveBeenCalledTimes(1);
    const output = JSON.parse(String(log.mock.calls[0]?.[0])) as Record<string, unknown>;
    expect(output).toMatchObject({
      schemaVersion: 1,
      status: 'unexecuted',
      mode: 'mock',
      task: 'Inspect the fixture repository',
      repo: {
        root,
        packageManager: 'pnpm',
        packageName: 'fixture-repository',
        validationScripts: ['lint', 'test'],
      },
      policy: { selected: 'SEARCH_REPO' },
    });
    expect(output).not.toHaveProperty('tracePath');
    expect(output).not.toHaveProperty('rawAnswers');
    expect(output).not.toHaveProperty('providerMetadata');
  });

  it('writes a versioned trace for an offline decision', async () => {
    const root = await temporaryRepository();
    const decision = await runDecision({
      repoPath: root,
      task: 'Inspect the fixture repository',
      mock: true,
      noTrace: false,
    }, root);
    const tracePath = decision.tracePath;

    expect(tracePath).toMatch(/^traces\/.+\.jsonl$/);
    const record = JSON.parse(await readFile(path.join(root, tracePath ?? ''), 'utf8')) as Record<string, unknown>;
    expect(record).toMatchObject({
      schemaVersion: 1,
      state: { repo: { root } },
      evaluation: {
        assessment: { nextAction: { choice: 'SEARCH_REPO' } },
      },
      policy: { selected: 'SEARCH_REPO' },
    });
    expect((record.evaluation as Record<string, unknown>)).not.toHaveProperty('providerMetadata');
  });

  it('fails before live evaluation when the gateway key is missing', async () => {
    const root = await temporaryRepository();
    vi.stubEnv('AI_GATEWAY_API_KEY', '');

    await expect(runDecision({
      repoPath: root,
      task: 'Inspect the fixture repository',
      mock: false,
      noTrace: true,
    }, root)).rejects.toThrow('AI_GATEWAY_API_KEY is required');
  });

  it('returns the safe trace error when an otherwise valid decision cannot be recorded', async () => {
    const root = await temporaryRepository();
    const blockedTraceRoot = path.join(root, 'blocked-trace-root');
    await writeFile(blockedTraceRoot, 'not a directory');

    await expect(runDecision({
      repoPath: root,
      task: 'Inspect the fixture repository',
      mock: true,
      noTrace: false,
    }, blockedTraceRoot)).rejects.toEqual(expect.objectContaining({
      name: 'TraceWriteError',
      message: expect.stringContaining('--no-trace'),
    } satisfies Partial<TraceWriteError>));
  });
});

