}

async function git(root: string, args: string[]): Promise<string> {
  return new Promise((resolve) => {
    const child = spawn('git', ['-c', 'core.fsmonitor=false', ...args], {
      cwd: root,
      stdio: ['ignore', 'pipe', 'ignore'],
      env: {
        ...process.env,
        GIT_OPTIONAL_LOCKS: '0',
        GIT_TERMINAL_PROMPT: '0',
      },
    });
    let output = '';
    let outputBytes = 0;
    let interrupted = false;
    let settled = false;
    const timeout = setTimeout(() => {
      interrupted = true;
      child.kill();
    }, GIT_TIMEOUT_MS);
    timeout.unref();

    const finish = (value: string): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      resolve(value);
    };

    child.stdout.on('data', (chunk: Buffer) => {
      if (interrupted) return;

      const availableBytes = MAX_GIT_OUTPUT_BYTES - outputBytes;
      if (availableBytes <= 0 || chunk.length > availableBytes) {
        interrupted = true;
        child.kill();
        return;
      }

      output += chunk.toString('utf8');
      outputBytes += chunk.length;
    });
    child.on('error', () => finish(''));
    child.on('close', (code) => finish(code === 0 && !interrupted ? output.trim() : ''));
  });
}

async function readTopLevelFiles(root: string): Promise<string[]> {
  const directory = await opendir(root);
  const entries: string[] = [];
  let scanned = 0;

  for await (const entry of directory) {
    scanned += 1;
    if (entry.name !== 'node_modules' && entry.name !== '.git') {
      entries.push(`${entry.name}${entry.isDirectory() ? '/' : ''}`);
    }
    if (scanned >= MAX_TOP_LEVEL_ENTRIES_SCANNED) break;
  }

  return entries.sort().slice(0, MAX_TOP_LEVEL_FILES);
}

async function readPackageMetadata(packageJsonPath: string): Promise<PackageMetadata> {
  if (!(await isRegularFile(packageJsonPath))) return { scripts: [] };

  try {
    const packageJson = await open(packageJsonPath, 'r');
    try {
      const contents = Buffer.alloc(MAX_PACKAGE_JSON_BYTES + 1);
      const { bytesRead } = await packageJson.read(contents, 0, contents.length, 0);
      if (bytesRead > MAX_PACKAGE_JSON_BYTES) return { scripts: [] };

      const parsed: unknown = JSON.parse(contents.subarray(0, bytesRead).toString('utf8'));
      if (!isRecord(parsed)) return { scripts: [] };

      const packageName = typeof parsed.name === 'string'
        ? truncateText(parsed.name, MAX_PACKAGE_NAME_LENGTH)
        : undefined;
      const scripts = isRecord(parsed.scripts)
        ? Object.entries(parsed.scripts)
          .filter(([, value]) => typeof value === 'string')
          .map(([name]) => truncateText(name, MAX_SCRIPT_NAME_LENGTH))
          .sort()
          .slice(0, MAX_SCRIPTS)
        : [];

      return { ...(packageName ? { packageName } : {}), scripts };
    } finally {
      await packageJson.close();
    }
  } catch {
    return { scripts: [] };
  }
}

async function detectPackageManager(root: string): Promise<RepoSnapshot['packageManager']> {
  if (await isRegularFile(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
  if (await isRegularFile(path.join(root, 'package-lock.json'))) return 'npm';
  if (await isRegularFile(path.join(root, 'yarn.lock'))) return 'yarn';
  if (
    (await isRegularFile(path.join(root, 'bun.lock'))) ||
    (await isRegularFile(path.join(root, 'bun.lockb')))
  ) {
    return 'bun';
  }
  return 'unknown';
}

async function inspectGit(root: string): Promise<Pick<RepoSnapshot, 'gitBranch' | 'gitStatus'>> {
  const gitRoot = await git(root, ['rev-parse', '--show-toplevel']);
  if (!gitRoot || path.resolve(gitRoot) !== root) return { gitStatus: [] };

  const [gitBranch, status] = await Promise.all([
    git(root, ['branch', '--show-current']),
    git(root, ['status', '--short', '--no-renames', '--untracked-files=normal']),
  ]);

  return {
    ...(gitBranch ? { gitBranch: truncateText(gitBranch, MAX_GIT_LINE_LENGTH) } : {}),
    gitStatus: status
      ? status
        .split('\n')
        .slice(0, MAX_GIT_STATUS_ENTRIES)
        .map((line) => truncateText(line, MAX_GIT_LINE_LENGTH))
      : [],
  };
}

export async function inspectRepo(inputPath: string): Promise<RepoSnapshot> {
  const root = path.resolve(inputPath);
  let rootStat;
  try {
    rootStat = await stat(root);
  } catch {
    throw new Error(`Repository path does not exist: ${root}`);
  }
  if (!rootStat.isDirectory()) throw new Error(`Repository path must be a directory: ${root}`);

  const packageJsonPath = path.join(root, 'package.json');
  const [topLevelFiles, packageMetadata, packageManager, gitMetadata] = await Promise.all([
    readTopLevelFiles(root),
    readPackageMetadata(packageJsonPath),
    detectPackageManager(root),
    inspectGit(root),
  ]);

  const validationNames = new Set(['test', 'check', 'typecheck', 'lint', 'build']);
  const validationScripts = packageMetadata.scripts.filter((script) =>
    [...validationNames].some((name) => script === name || script.startsWith(`${name}:`)),
  );

  return {
    root,
    packageManager,
    ...(packageMetadata.packageName ? { packageName: packageMetadata.packageName } : {}),
    scripts: packageMetadata.scripts,
    validationScripts,
    ...gitMetadata,
    topLevelFiles,
  };
}
import { execFile as execFileCallback } from 'node:child_process';
import { mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import { afterEach, describe, expect, it } from 'vitest';
import {
  inspectRepo,
  MAX_GIT_OUTPUT_BYTES,
  MAX_GIT_STATUS_ENTRIES,
  MAX_PACKAGE_JSON_BYTES,
  MAX_SCRIPTS,
  MAX_TOP_LEVEL_FILES,
} from './inspect.js';

const execFile = promisify(execFileCallback);
const temporaryRoots: string[] = [];

async function createRepositoryDirectory(): Promise<string> {
  const root = await mkdtemp(path.join(tmpdir(), 'jev-inspect-'));
  temporaryRoots.push(root);
  return root;
}

afterEach(async () => {
  await Promise.all(temporaryRoots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
});

describe('inspectRepo', () => {
  it('rejects a missing path and a path that is not a directory', async () => {
    const root = await createRepositoryDirectory();
    const file = path.join(root, 'not-a-directory');
    await writeFile(file, 'contents');

    await expect(inspectRepo(path.join(root, 'missing'))).rejects.toThrow(
      'Repository path does not exist',
    );
    await expect(inspectRepo(file)).rejects.toThrow('Repository path must be a directory');
  });

  it('treats malformed package metadata as unavailable', async () => {
    const root = await createRepositoryDirectory();
    await writeFile(path.join(root, 'package.json'), '{ not valid json');
    await writeFile(path.join(root, 'pnpm-lock.yaml'), 'lockfileVersion: 9');

    const snapshot = await inspectRepo(root);

    expect(snapshot).toMatchObject({
      packageManager: 'pnpm',
      scripts: [],
      validationScripts: [],
      gitStatus: [],
    });
    expect(snapshot.packageName).toBeUndefined();
    expect(snapshot.gitBranch).toBeUndefined();
  });

  it('does not inherit Git metadata from an ancestor repository', async () => {
    const root = await createRepositoryDirectory();
    const nestedDirectory = path.join(root, 'nested');
    await execFile('git', ['init', '--quiet'], { cwd: root });
    await mkdir(nestedDirectory);

    const snapshot = await inspectRepo(nestedDirectory);

    expect(snapshot.gitStatus).toEqual([]);
    expect(snapshot.gitBranch).toBeUndefined();
  });

  it('treats an oversized package manifest as unavailable', async () => {
    const root = await createRepositoryDirectory();
    await writeFile(
      path.join(root, 'package.json'),
      JSON.stringify({ name: 'x'.repeat(MAX_PACKAGE_JSON_BYTES) }),
    );

    const snapshot = await inspectRepo(root);

    expect(snapshot.packageName).toBeUndefined();
    expect(snapshot.scripts).toEqual([]);
  });

  it('bounds scripts and top-level metadata', async () => {
    const root = await createRepositoryDirectory();
    const scripts = Object.fromEntries(
      Array.from({ length: MAX_SCRIPTS + 20 }, (_, index) => [
        `test:${String(index).padStart(3, '0')}`,
        'vitest run',
      ]),
    );
    await writeFile(path.join(root, 'package.json'), JSON.stringify({ name: 'bounded', scripts }));
    await Promise.all(
      Array.from({ length: MAX_TOP_LEVEL_FILES + 20 }, (_, index) =>
        writeFile(path.join(root, `source-${String(index).padStart(3, '0')}.ts`), ''),
      ),
    );

    const snapshot = await inspectRepo(root);

    expect(snapshot.scripts).toHaveLength(MAX_SCRIPTS);
    expect(snapshot.validationScripts).toHaveLength(MAX_SCRIPTS);
    expect(snapshot.topLevelFiles).toHaveLength(MAX_TOP_LEVEL_FILES);
  });

  it('bounds Git status entries for a repository root', async () => {
    const root = await createRepositoryDirectory();
    await execFile('git', ['init', '--quiet'], { cwd: root });
    await Promise.all(
      Array.from({ length: MAX_GIT_STATUS_ENTRIES + 20 }, (_, index) =>
        writeFile(path.join(root, `untracked-${String(index).padStart(3, '0')}.txt`), ''),
      ),
    );

    const snapshot = await inspectRepo(root);

    expect(snapshot.gitStatus).toHaveLength(MAX_GIT_STATUS_ENTRIES);
  });

  it('stops collecting oversized Git output', async () => {
    const root = await createRepositoryDirectory();
    await execFile('git', ['init', '--quiet'], { cwd: root });
    const filenameLength = 240;
    const fileCount = Math.ceil(MAX_GIT_OUTPUT_BYTES / filenameLength) + 5;
    await Promise.all(
      Array.from({ length: fileCount }, (_, index) => {
        const prefix = `untracked-${String(index).padStart(3, '0')}-`;
        return writeFile(path.join(root, `${prefix}${'x'.repeat(filenameLength - prefix.length)}`), '');
      }),
    );

    const snapshot = await inspectRepo(root);

    expect(snapshot.gitStatus).toEqual([]);
  });
});
import { randomUUID } from 'node:crypto';
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { AgentState, EvaluationResult, PolicyDecision } from '../types.js';

export const TRACE_SCHEMA_VERSION = 1;
export const MAX_TRACE_VALUE_BYTES = 8 * 1024;

const MAX_TRACE_DEPTH = 6;
const MAX_TRACE_ARRAY_ITEMS = 32;
const MAX_TRACE_OBJECT_ENTRIES = 32;
const MAX_TRACE_STRING_LENGTH = 1_024;
const MAX_TRACE_TEXT_BUDGET = 6_000;
const MAX_TRACE_WRITE_ATTEMPTS = 3;
const REDACTED = '[REDACTED]';
const TRUNCATED = '[TRUNCATED]';
const SENSITIVE_KEY = /api[-_ ]?key|authorization|token|secret|password|credential|cookie|session/i;
const KEY_VALUE_SECRET = /((?:api[-_ ]?key|authorization|token|secret|password|credential|cookie|session)\s*[:=]\s*)(?:(?:Bearer\s+)[^\s,;]+|"[^"]*"|'[^']*'|[^\s,;]+)/gi;
const BEARER_TOKEN = /(\bBearer\s+)[A-Za-z0-9._~+/=-]+/gi;

export type TraceValue =
  | null
  | boolean
  | number
  | string
  | TraceValue[]
  | { [key: string]: TraceValue };

export type TraceRecord = {
  schemaVersion: typeof TRACE_SCHEMA_VERSION;
  runId: string;
  timestamp: string;
  state: TraceValue;
  evaluation: {
    assessment: TraceValue;
    model: string;
    latencyMs: number;
    rawAnswers: TraceValue;
  };
  policy: TraceValue;
};

export class TraceWriteError extends Error {
  constructor() {
    super('Unable to write the decision trace. Re-run with --no-trace only when an unrecorded decision is acceptable.');
    this.name = 'TraceWriteError';
  }
}

type SanitizationContext = {
  remainingText: number;
  seen: WeakSet<object>;
  secretValues: string[];
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function configuredSecretValues(): string[] {
  const gatewayKey = process.env.AI_GATEWAY_API_KEY?.trim();
  return gatewayKey ? [gatewayKey] : [];
}

function redactText(value: string, secretValues: string[]): string {
  let redacted = value;
  for (const secret of secretValues) {
    redacted = redacted.replaceAll(secret, REDACTED);
  }
  return redacted
    .replace(KEY_VALUE_SECRET, `$1${REDACTED}`)
    .replace(BEARER_TOKEN, `$1${REDACTED}`);
}

function takeText(value: string, context: SanitizationContext): string {
  const redacted = redactText(value, context.secretValues);
  const available = Math.min(MAX_TRACE_STRING_LENGTH, context.remainingText);
  if (available <= 0) return TRUNCATED;
  context.remainingText -= Math.min(redacted.length, available);
  return redacted.length > available ? `${redacted.slice(0, available)}${TRUNCATED}` : redacted;
}

function sanitizeValue(value: unknown, context: SanitizationContext, depth: number): TraceValue {
  if (depth > MAX_TRACE_DEPTH) return TRUNCATED;
  if (value === undefined) return '[UNDEFINED]';
  if (value === null || typeof value === 'boolean') return value;
  if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
  if (typeof value === 'string') return takeText(value, context);
  if (typeof value === 'bigint' || typeof value === 'symbol' || typeof value === 'function') {
    return takeText(String(value), context);
  }

  if (context.seen.has(value)) return '[CIRCULAR]';
  context.seen.add(value);

  if (Array.isArray(value)) {
    const items = value.slice(0, MAX_TRACE_ARRAY_ITEMS)
      .map((item) => sanitizeValue(item, context, depth + 1));
    if (value.length > MAX_TRACE_ARRAY_ITEMS) items.push(TRUNCATED);
    return items;
  }

  if (!isRecord(value)) return takeText(String(value), context);

  const entries: { [key: string]: TraceValue } = {};
  const objectEntries = Object.entries(value).slice(0, MAX_TRACE_OBJECT_ENTRIES);
  for (const [key, entry] of objectEntries) {
    entries[key] = SENSITIVE_KEY.test(key)
      ? REDACTED
      : sanitizeValue(entry, context, depth + 1);
  }
  if (Object.keys(value).length > MAX_TRACE_OBJECT_ENTRIES) entries.truncated = TRUNCATED;
  return entries;
}

export function sanitizeTraceValue(
  value: unknown,
  secretValues: string[] = configuredSecretValues(),
): TraceValue {
  const sanitized = sanitizeValue(value, {
    remainingText: MAX_TRACE_TEXT_BUDGET,
    seen: new WeakSet<object>(),
    secretValues,
  }, 0);
  const serialized = JSON.stringify(sanitized);
  if (Buffer.byteLength(serialized, 'utf8') <= MAX_TRACE_VALUE_BYTES) return sanitized;

  return {
    truncated: true,
    preview: takeText(serialized, {
      remainingText: Math.floor(MAX_TRACE_VALUE_BYTES / 4),
      seen: new WeakSet<object>(),
      secretValues,
    }),
  };
}

function makeTraceRecord(
  payload: {
    state: AgentState;
    evaluation: EvaluationResult;
    policy: PolicyDecision;
  },
  date: Date,
  runId: string,
): TraceRecord {
  const secretValues = configuredSecretValues();
  return {
    schemaVersion: TRACE_SCHEMA_VERSION,
    runId,
    timestamp: date.toISOString(),
    state: sanitizeTraceValue(payload.state, secretValues),
    evaluation: {
      assessment: sanitizeTraceValue(payload.evaluation.assessment, secretValues),
      model: redactText(payload.evaluation.model, secretValues),
      latencyMs: Number.isFinite(payload.evaluation.latencyMs) ? payload.evaluation.latencyMs : 0,
      rawAnswers: sanitizeTraceValue(payload.evaluation.rawAnswers, secretValues),
    },
    policy: sanitizeTraceValue(payload.policy, secretValues),
  };
}

function isFileExistsError(error: unknown): boolean {
  return isRecord(error) && error.code === 'EEXIST';
}

export async function writeTrace(
  root: string,
  payload: {
    state: AgentState;
    evaluation: EvaluationResult;
    policy: PolicyDecision;
  },
): Promise<string> {
  try {
    const traceDir = path.join(root, 'traces');
    await mkdir(traceDir, { recursive: true });

    for (let attempt = 0; attempt < MAX_TRACE_WRITE_ATTEMPTS; attempt += 1) {
      const date = new Date();
      const runId = `${date.toISOString().replaceAll(':', '-').replaceAll('.', '-')}-${randomUUID()}`;
      const tracePath = path.join(traceDir, `${runId}.jsonl`);
      const record = makeTraceRecord(payload, date, runId);

      try {
        await writeFile(tracePath, `${JSON.stringify(record)}\n`, { flag: 'wx' });
        return tracePath;
      } catch (error) {
        if (isFileExistsError(error)) continue;
        throw error;
      }
    }
  } catch {
    throw new TraceWriteError();
  }

  throw new TraceWriteError();
}
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import {
  MAX_TRACE_VALUE_BYTES,
  sanitizeTraceValue,
  TraceWriteError,
  writeTrace,
} from './trace.js';
import type { AgentState, EvaluationResult, PolicyDecision } from '../types.js';

const roots: string[] = [];

async function temporaryRoot(): Promise<string> {
  const root = await mkdtemp(path.join(os.tmpdir(), 'jev-trace-'));
  roots.push(root);
  return root;
}

afterEach(async () => {
  await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
});

const state: AgentState = {
  task: 'Investigate authorization: Bearer task-token-value',
  iteration: 1,
  currentGoal: 'Choose the next action',
  repo: {
    root: '/repo',
    packageManager: 'pnpm',
    scripts: ['test'],
    validationScripts: ['test'],
    gitStatus: [],
    topLevelFiles: ['package.json'],
  },
  filesRead: [],
  filesModified: [],
  observations: [],
  commandsRun: [],
  tests: { ran: false },
  failedApproaches: [],
  codexCalls: 0,
};

const policy: PolicyDecision = {
  requested: 'SEARCH_REPO',
  selected: 'SEARCH_REPO',
  override: false,
  reason: 'Clear recommendation.',
};

function evaluation(rawAnswers: unknown): EvaluationResult {
  return {
    assessment: {
      taskComplete: { probability: 0.1 },
      needsMoreInformation: { probability: 0.1 },
      needsTesting: { probability: 0.1 },
      stuck: { probability: 0.1 },
      nextAction: {
        choice: 'SEARCH_REPO',
        probabilities: { SEARCH_REPO: 0.8 },
        confidence: 0.7,
      },
    },
    model: 'typesafe-ai/jev',
    latencyMs: 12,
    providerMetadata: { apiKey: 'provider-secret-value' },
    rawAnswers,
  };
}

describe('writeTrace', () => {
  it('redacts configured credential values in ordinary text fields', () => {
    const sanitized = sanitizeTraceValue(
      { note: 'The configured value is gateway-key-value.' },
      ['gateway-key-value'],
    );

    expect(JSON.stringify(sanitized)).not.toContain('gateway-key-value');
  });

  it('writes a versioned, unique record without raw provider metadata or secrets', async () => {
    const root = await temporaryRoot();
    const payload = {
      state,
      evaluation: evaluation({
        apiKey: 'raw-api-key-value',
        explanation: 'authorization: Bearer raw-bearer-token',
        nested: { token: 'nested-token-value' },
      }),
      policy,
    };

    const firstPath = await writeTrace(root, payload);
    const secondPath = await writeTrace(root, payload);
    const record = JSON.parse(await readFile(firstPath, 'utf8')) as Record<string, unknown>;
    const serialized = JSON.stringify(record);

    expect(firstPath).not.toBe(secondPath);
    expect(record).toMatchObject({
      schemaVersion: 1,
      runId: expect.stringMatching(/^\d{4}-\d{2}-\d{2}T.+-[0-9a-f-]{36}$/),
      state: { task: 'Investigate authorization: [REDACTED]' },
      evaluation: {
        model: 'typesafe-ai/jev',
        latencyMs: 12,
      },
      policy,
    });
    expect((record.evaluation as Record<string, unknown>)).not.toHaveProperty('providerMetadata');
    expect(serialized).not.toContain('provider-secret-value');
    expect(serialized).not.toContain('task-token-value');
    expect(serialized).not.toContain('raw-api-key-value');
    expect(serialized).not.toContain('raw-bearer-token');
    expect(serialized).not.toContain('nested-token-value');
  });

  it('bounds an oversized raw-answer payload', async () => {
    const root = await temporaryRoot();
    const tracePath = await writeTrace(root, {
      state,
      evaluation: evaluation({ answer: 'x'.repeat(MAX_TRACE_VALUE_BYTES * 2) }),
      policy,
    });
    const record = JSON.parse(await readFile(tracePath, 'utf8')) as {
      evaluation: { rawAnswers: unknown };
    };

    expect(Buffer.byteLength(JSON.stringify(record.evaluation.rawAnswers), 'utf8')).toBeLessThanOrEqual(
      MAX_TRACE_VALUE_BYTES,
    );
  });

  it('returns a credential-safe error when the trace directory cannot be created', async () => {
    const root = await temporaryRoot();
    const file = path.join(root, 'not-a-directory');
    await writeFile(file, 'not a directory');

    await expect(writeTrace(file, {
      state,
      evaluation: evaluation({}),
      policy,
    })).rejects.toEqual(expect.objectContaining({
      name: 'TraceWriteError',
      message: expect.stringContaining('--no-trace'),
    } satisfies Partial<TraceWriteError>));
  });
});

