import {
  APICallError,
  experimental_evaluate as evaluate,
  InvalidResponseDataError,
  NoSuchModelError,
  RetryError,
  type Experimental_EvaluationModel as EvaluationModel,
} from 'ai';
import type { Action, AgentAssessment, AgentState, EvaluationResult } from '../types.js';
import {
  limitStrings,
  MAX_EVALUATION_COMMAND_OUTPUT_LENGTH,
  MAX_EVALUATION_COMMANDS,
  MAX_EVALUATION_LIST_ITEMS,
  MAX_EVALUATION_TEXT_LENGTH,
  MAX_TASK_LENGTH,
  truncateText,
} from '../limits.js';

export const JEV_EVALUATION_TIMEOUT_MS = 10_000;
export const JEV_EVALUATION_MAX_RETRIES = 1;

export type JevEvaluationErrorCode =
  | 'timeout'
  | 'authentication'
  | 'rate_limit'
  | 'model_unavailable'
  | 'invalid_response'
  | 'service_unavailable'
  | 'request_failed';

export class JevEvaluationError extends Error {
  readonly code: JevEvaluationErrorCode;

  constructor(code: JevEvaluationErrorCode, message: string) {
    super(message);
    this.name = 'JevEvaluationError';
    this.code = code;
  }
}

const ACTION_CRITERIA = {
  SEARCH_REPO: 'Search repository contents to locate relevant code or configuration.',
  READ_FILE: 'Inspect one or more known files before deciding what to change.',
  RUN_COMMAND: 'Run a safe, non-destructive diagnostic command.',
  RUN_TESTS: 'Run an existing test, typecheck, lint, or build validation script.',
  CALL_CODEX: 'Delegate implementation or deeper coding analysis to Codex.',
  ASK_USER: 'Required information or authorization is unavailable and must come from the user.',
  FINISH: 'The requested task is complete and adequately validated.',
} as const;

export function boundAgentStateForEvaluation(state: AgentState): AgentState {
  const { repo } = state;
  return {
    ...state,
    task: truncateText(state.task, MAX_TASK_LENGTH),
    currentGoal: truncateText(state.currentGoal, MAX_EVALUATION_TEXT_LENGTH),
    repo: {
      root: truncateText(repo.root, MAX_EVALUATION_TEXT_LENGTH),
      packageManager: repo.packageManager,
      ...(repo.packageName
        ? { packageName: truncateText(repo.packageName, MAX_EVALUATION_TEXT_LENGTH) }
        : {}),
      scripts: limitStrings(repo.scripts),
      validationScripts: limitStrings(repo.validationScripts),
      ...(repo.gitBranch
        ? { gitBranch: truncateText(repo.gitBranch, MAX_EVALUATION_TEXT_LENGTH) }
        : {}),
      gitStatus: limitStrings(repo.gitStatus),
      topLevelFiles: limitStrings(repo.topLevelFiles),
    },
    filesRead: limitStrings(state.filesRead),
    filesModified: limitStrings(state.filesModified),
    observations: limitStrings(state.observations),
    commandsRun: state.commandsRun.slice(0, MAX_EVALUATION_COMMANDS).map((command) => ({
      command: truncateText(command.command, MAX_EVALUATION_TEXT_LENGTH),
      exitCode: command.exitCode,
      output: truncateText(command.output, MAX_EVALUATION_COMMAND_OUTPUT_LENGTH),
    })),
    tests: {
      ran: state.tests.ran,
      ...(state.tests.passed !== undefined ? { passed: state.tests.passed } : {}),
      ...(state.tests.summary !== undefined
        ? { summary: truncateText(state.tests.summary, MAX_EVALUATION_TEXT_LENGTH) }
        : {}),
    },
    failedApproaches: limitStrings(state.failedApproaches, MAX_EVALUATION_LIST_ITEMS),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function isProbability(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1;
}

function invalidProviderMetadata(): never {
  throw new JevEvaluationError(
    'invalid_response',
    'Jev returned invalid provider metadata.',
  );
}

function getNextActionConfidence(providerMetadata: unknown): number | undefined {
  if (providerMetadata === undefined) return undefined;
  if (!isRecord(providerMetadata)) invalidProviderMetadata();

  const typesafe = providerMetadata.typesafe;
  if (typesafe === undefined) return undefined;
  if (!isRecord(typesafe)) invalidProviderMetadata();

  const confidence = typesafe.confidence;
  if (confidence === undefined) return undefined;
  if (!isRecord(confidence)) invalidProviderMetadata();

  const nextAction = confidence.nextAction;
  if (nextAction === undefined) return undefined;
  if (!isProbability(nextAction)) invalidProviderMetadata();

  return nextAction;
}

function isTimeoutError(error: unknown): boolean {
  return (
    (RetryError.isInstance(error) && error.reason === 'abort') ||
    (error instanceof Error && (error.name === 'AbortError' || error.name === 'TimeoutError'))
  );
}

function lastEvaluationError(error: unknown): unknown {
  return RetryError.isInstance(error) ? error.lastError : error;
}

function getStatusCode(error: unknown): number | undefined {
  if (APICallError.isInstance(error)) return error.statusCode;
  if (!isRecord(error)) return undefined;
  const statusCode = error.statusCode;
  return typeof statusCode === 'number' && Number.isInteger(statusCode)
    ? statusCode
    : undefined;
}

export function normalizeJevEvaluationError(error: unknown): JevEvaluationError {
  if (error instanceof JevEvaluationError) return error;
  if (isTimeoutError(error)) {
    return new JevEvaluationError(
      'timeout',
      `Jev evaluation timed out after ${JEV_EVALUATION_TIMEOUT_MS / 1000} seconds.`,
    );
  }

  const lastError = lastEvaluationError(error);
  if (InvalidResponseDataError.isInstance(lastError)) {
    return new JevEvaluationError('invalid_response', 'Jev returned invalid evaluation data.');
  }
  if (NoSuchModelError.isInstance(lastError)) {
    return new JevEvaluationError(
      'model_unavailable',
      'The configured Jev model is unavailable. Check ROUTER_MODEL and Gateway access.',
    );
  }

  switch (getStatusCode(lastError)) {
    case 401:
    case 403:
      return new JevEvaluationError(
        'authentication',
        'Jev Gateway authentication or authorization failed. Check AI_GATEWAY_API_KEY and Gateway access.',
      );
    case 404:
      return new JevEvaluationError(
        'model_unavailable',
        'The configured Jev model is unavailable. Check ROUTER_MODEL and Gateway access.',
      );
    case 429:
      return new JevEvaluationError(
        'rate_limit',
        'Jev Gateway rate limit reached. Wait before retrying the evaluation.',
      );
    default: {
      const statusCode = getStatusCode(lastError);
      if (statusCode !== undefined && statusCode >= 500) {
        return new JevEvaluationError(
          'service_unavailable',
          'Jev Gateway is temporarily unavailable. Try the evaluation again later.',
        );
      }
      return new JevEvaluationError(
        'request_failed',
        'Jev evaluation failed. Try the evaluation again later.',
      );
    }
  }
}

export async function evaluateAgentState(
  state: AgentState,
  model: EvaluationModel = process.env.ROUTER_MODEL ?? 'typesafe-ai/jev',
): Promise<EvaluationResult> {
  const startedAt = performance.now();
  const evaluation = evaluate({
    model,
    state: boundAgentStateForEvaluation(state),
    questions: {
      taskComplete: {
        type: 'boolean',
        instructions: 'Has the original requested coding task been completed and validated?',
        criteria: {
          true: 'The requested outcome exists and available validation supports completion.',
          false: 'Work, evidence, or validation is still missing.',
        },
      },
      needsMoreInformation: {
        type: 'boolean',
        instructions: 'Is information required that cannot be obtained from the repository or safe local inspection?',
      },
      needsTesting: {
        type: 'boolean',
        instructions: 'Should the current implementation or hypothesis be validated now?',
      },
      stuck: {
        type: 'boolean',
        instructions: 'Is the workflow repeating failed approaches or failing to make meaningful progress?',
      },
      nextAction: {
        type: 'choice',
        instructions: 'Which single action would most effectively and safely advance the coding task?',
        criteria: ACTION_CRITERIA,
      },
    },
    maxRetries: JEV_EVALUATION_MAX_RETRIES,
    abortSignal: AbortSignal.timeout(JEV_EVALUATION_TIMEOUT_MS),
    providerOptions: {
      gateway: {
        zeroDataRetention: false,
      },
    },
  });
  let result: Awaited<typeof evaluation>;

  try {
    result = await evaluation;
  } catch (error) {
    throw normalizeJevEvaluationError(error);
  }

  const confidence = getNextActionConfidence(result.providerMetadata);
  const { taskComplete, needsMoreInformation, needsTesting, stuck, nextAction } = result.answers;

  const assessment: AgentAssessment = {
    taskComplete: { probability: taskComplete.probability },
    needsMoreInformation: { probability: needsMoreInformation.probability },
    needsTesting: { probability: needsTesting.probability },
    stuck: { probability: stuck.probability },
    nextAction: {
      choice: nextAction.choice as Action,
      probabilities: nextAction.probabilities ?? {},
      ...(confidence !== undefined ? { confidence } : {}),
    },
  };

  return {
    assessment,
    model: typeof model === 'string' ? model : process.env.ROUTER_MODEL ?? 'evaluation-model',
    latencyMs: Math.round(performance.now() - startedAt),
    ...(result.providerMetadata ? { providerMetadata: result.providerMetadata } : {}),
    rawAnswers: result.answers,
  };
}
import type { EvaluationResult } from './types.js';

export function mockEvaluation(): EvaluationResult {
  const probabilities = {
    SEARCH_REPO: 0.68,
    READ_FILE: 0.16,
    RUN_COMMAND: 0.04,
    RUN_TESTS: 0.03,
    CALL_CODEX: 0.05,
    ASK_USER: 0.03,
    FINISH: 0.01,
  } as const;

  return {
    assessment: {
      taskComplete: { probability: 0.02 },
      needsMoreInformation: { probability: 0.08 },
      needsTesting: { probability: 0.09 },
      stuck: { probability: 0.01 },
      nextAction: {
        choice: 'SEARCH_REPO',
        probabilities,
        confidence: 0.71,
      },
    },
    model: 'mock/jev',
    latencyMs: 0,
    rawAnswers: { mock: true },
  };
}
export function requireGatewayApiKey(environment: NodeJS.ProcessEnv = process.env): void {
  if (!environment.AI_GATEWAY_API_KEY?.trim()) {
    throw new Error(
      'AI_GATEWAY_API_KEY is required for live Jev evaluation. Add it to .env and run Node with --env-file=.env, or export it before running the CLI.',
    );
  }
}
export const MAX_TASK_LENGTH = 4_000;
export const MAX_EVALUATION_TEXT_LENGTH = 2_000;
export const MAX_EVALUATION_LIST_ITEMS = 100;
export const MAX_EVALUATION_COMMANDS = 20;
export const MAX_EVALUATION_COMMAND_OUTPUT_LENGTH = 2_000;

const TRUNCATION_MARKER = '… [truncated]';

export function truncateText(value: string, maximumLength: number): string {
  if (value.length <= maximumLength) return value;
  if (maximumLength <= 0) return '';
  if (maximumLength <= TRUNCATION_MARKER.length) return value.slice(0, maximumLength);

  const contentLength = maximumLength - TRUNCATION_MARKER.length;
  return `${value.slice(0, contentLength)}${TRUNCATION_MARKER}`;
}

export function limitStrings(
  values: string[],
  maximumItems: number = MAX_EVALUATION_LIST_ITEMS,
  maximumLength: number = MAX_EVALUATION_TEXT_LENGTH,
): string[] {
  return values.slice(0, maximumItems).map((value) => truncateText(value, maximumLength));
}

export function requireBoundedTask(task: string): string {
  if (task.length > MAX_TASK_LENGTH) {
    throw new Error(`Task exceeds the ${MAX_TASK_LENGTH}-character limit.`);
  }
  return task;
}
# Jev Orchestrator

A deliberately small Node/TypeScript experiment for testing whether
`typesafe-ai/jev` can make useful next-step decisions around a coding agent.

The current milestone is **decision-only**. It inspects a repository, sends a
compact state object to Jev through Vercel AI Gateway, applies deterministic
policy thresholds, prints the result, and records a JSONL trace. It does not yet
edit files, execute tests, or call Codex.

## Requirements

- Node.js 22+
- pnpm
- A Vercel AI Gateway key for live mode

## Setup

```bash
pnpm install
cp .env.example .env
```

Add your key to `.env`, then use Node's env-file support to load it:

```bash
pnpm exec node --env-file=.env --import tsx src/cli.ts -- \
  . "Inspect this repo and choose the safest useful first action"
```

Never commit `.env`; it is ignored by git.

## Run

First verify the full local flow without spending tokens:

```bash
pnpm dev -- . "Inspect this repo and choose the safest useful first action" --mock
```

Then run the live Jev evaluation with the key from `.env`:

```bash
pnpm exec node --env-file=.env --import tsx src/cli.ts -- \
  . "Inspect this repo and choose the safest useful first action"
```

Each live evaluation has a 10-second deadline and at most one retry for a
transient Gateway failure. The CLI reports authentication, rate-limit,
unavailable-model, timeout, and malformed-response failures without printing
Gateway response data.

## CLI contract

Every successful run prints an **unexecuted** decision. The CLI does not run
the selected tool or coding agent in this milestone.

```bash
jev-agent <repo-path> <task> [--mock] [--no-trace] [--json]
```

- `--mock` uses the offline deterministic evaluation.
- `--no-trace` suppresses the JSONL trace file.
- `--json` writes exactly one normalized, machine-readable decision object to
  stdout. It includes the repository snapshot, task, assessment, deterministic
  policy decision, model name, latency, and optional trace path. It omits raw
  provider answers and provider metadata.
- `--version` prints the installed package version; `--help` (or `-h`) prints
  usage.

For example, a token-free machine-readable run is:

```bash
pnpm dev -- . "Inspect this repo and choose the safest useful first action" \
  --mock --no-trace --json
```

Exit code `0` means a decision, help text, or version was printed. Exit code
`1` means an operational failure prevented a decision; exit code `2` means
invalid command-line usage. In `--json` mode, errors are one JSON object on
stderr with the same exit code.

## Traces

Unless `--no-trace` is set, each successful decision writes one JSONL record
under `./traces/`. Records use trace schema version `1` and a timestamp-plus-
UUID run ID, so concurrent runs do not share a file. A record contains a
sanitized state snapshot, normalized assessment, policy decision, model,
latency, and bounded raw Jev answers. It deliberately excludes raw provider
metadata and upstream error bodies; known credential values and common
credential-shaped fields are redacted before writing.

Trace recording is part of the default auditable run. If the trace directory
cannot be created or written, the CLI returns operational exit code `1` and
does not print a decision. Use `--no-trace` only when an unrecorded decision is
acceptable.

## Inspection bounds

The target must be an existing directory. Repository inspection is read-only
and bounds the task to 4,000 characters, package metadata to 64 KiB, and Git
output and snapshot lists to small fixed limits before sending state to Jev.
Malformed or oversized `package.json` files and non-Git directories are handled
as incomplete metadata rather than causing a model request to fail.

After exporting `AI_GATEWAY_API_KEY`, the shorter command works as well. Against
another repository:

```bash
pnpm dev -- ../my-app "Fix the preview route returning 401 in production"
```

## Verify

```bash
pnpm check
pnpm test
pnpm build
```

The test suite is offline: it uses temporary repositories and mocked AI SDK
boundaries, so it does not require `AI_GATEWAY_API_KEY`, a coding agent, or a
live Jev evaluation. Pull-request CI runs the same typecheck, test, and build
commands for maintainers.

## Packaged CLI verification

The tarball contains the compiled runtime JavaScript and declarations under
`dist/`, plus the README and license. Test sources and compiled test files are
not published. The `prepack` lifecycle runs the production build before a
tarball is created.

To verify the package in your own separate project, first create a tarball from
this repository:

```bash
pnpm pack --out /absolute/path/to/jev-orchestrator-%v.tgz
```

Then, from the other project, install that exact archive and run the installed
binary against that project:

```bash
pnpm add --save-dev /absolute/path/to/jev-orchestrator-0.1.0.tgz
pnpm exec jev-agent --version
pnpm exec jev-agent . "Inspect this repository and choose the safest useful first action" \
  --mock --no-trace --json
```

The expected mock result is one JSON object with `status: "unexecuted"`; it
must not edit the target project or require an API key. Do not pack or publish
`.env`, traces, build cache, or `node_modules`.

## Continuous integration

The `Verify` workflow runs on pull requests targeting `main` from the trusted
`main` workflow definition. It uses no Gateway credentials and runs
`pnpm check`, `pnpm test`, and `pnpm build` only when GitHub reports the PR
author has effective `write` or `admin` repository permission. The permission
check itself does not check out or execute PR code; only after it passes does
the workflow check out the PR head without persisted credentials. For everyone
else, verification is skipped.

## Entire Cloud trails and reviews

Entire is enabled for this repository and syncs Codex checkpoints to the
configured remote. The checked-in `.entire/runners/` definitions run in Entire
Cloud: they produce a change summary, confidence, drift, risk, and security
signals, plus line-level review findings. They use read-only repository access
and are triggered from Trail push events; no local `entire review` command or
local model is part of this workflow.

Create a Trail for a branch before pushing its changes:

```bash
entire trail create --title "Describe the change" --type task
```

Review the summary, monitors, and findings in Entire Cloud. The default runner
definitions are intentionally generic; tailor them in a future reviewed change
once the repository has enough conventions to encode.

## Current safety boundary

This version is read-only except for trace files written under `./traces` in
the directory where the CLI is launched. The policy refuses to finish a task
until a detected validation script has passed, routes high missing-information
or stuck signals to `ASK_USER`, and does the same for ambiguous next actions.
If detected validation fails or none is available, the policy asks the user
rather than assuming completion or blindly retrying it.
Live Jev evaluations allow standard Gateway data retention
(`zeroDataRetention: false`); run them only with repository data you authorize
for that service.

## Next milestone

Add an approval-gated loop with constrained implementations of:

1. `SEARCH_REPO`
2. `READ_FILE`
3. `RUN_TESTS`
4. `CALL_CODEX`

The hard rules remain authoritative: no deploy, publish, push, destructive git,
filesystem writes outside the selected repository, or secret access.

