  1	#!/usr/bin/env node
  2	import { readFile } from 'node:fs/promises';
  3	import path from 'node:path';
  4	import { pathToFileURL } from 'node:url';
  5	import { evaluateAgentState } from './ai/evaluate.js';
  6	import { requireGatewayApiKey } from './config.js';
  7	import { requireBoundedTask } from './limits.js';
  8	import { writeTrace } from './logging/trace.js';
  9	import { mockEvaluation } from './mock.js';
 10	import { applyPolicy } from './policy.js';
 11	import { inspectRepo } from './repo/inspect.js';
 12	import type {
 13	  Action,
 14	  AgentAssessment,
 15	  AgentState,
 16	  EvaluationResult,
 17	  PolicyDecision,
 18	  RepoSnapshot,
 19	} from './types.js';
 20	
 21	export const EXIT_CODES = {
 22	  success: 0,
 23	  operationalError: 1,
 24	  usageError: 2,
 25	} as const;
 26	
 27	export type CliOptions = {
 28	  repoPath: string;
 29	  task: string;
 30	  mock: boolean;
 31	  noTrace: boolean;
 32	  json: boolean;
 33	};
 34	
 35	export type CliCommand =
 36	  | { kind: 'help' }
 37	  | { kind: 'version' }
 38	  | { kind: 'run'; options: CliOptions };
 39	
 40	export type DecisionOutput = {
 41	  schemaVersion: 1;
 42	  status: 'unexecuted';
 43	  mode: 'mock' | 'live';
 44	  repo: RepoSnapshot;
 45	  task: string;
 46	  assessment: AgentAssessment;
 47	  policy: PolicyDecision;
 48	  model: string;
 49	  latencyMs: number;
 50	  tracePath?: string;
 51	};
 52	
 53	type ErrorOutput = {
 54	  schemaVersion: 1;
 55	  status: 'error';
 56	  error: {
 57	    kind: 'usage' | 'operational';
 58	    message: string;
 59	  };
 60	  exitCode: number;
 61	};
 62	
 63	export class CliUsageError extends Error {
 64	  constructor(message: string) {
 65	    super(message);
 66	    this.name = 'CliUsageError';
 67	  }
 68	}
 69	
 70	export function usage(): string {
 71	  return `jev-agent <repo-path> <task> [--mock] [--no-trace] [--json]
 72	
 73	Options:
 74	  --mock       Use the offline deterministic evaluation.
 75	  --no-trace   Do not write a JSONL trace.
 76	  --json       Write one machine-readable decision to stdout.
 77	  --version    Print the installed package version.
 78	  --help, -h   Print this help text.
 79	
 80	Examples:
 81	  pnpm dev -- . "Decide what to inspect first"
 82	  pnpm dev -- ../my-app "Fix preview auth" --mock --json --no-trace
 83	
 84	Environment:
 85	  AI_GATEWAY_API_KEY   Vercel AI Gateway key
 86	  ROUTER_MODEL         Defaults to typesafe-ai/jev
 87	
 88	Exit codes:
 89	  0  A decision, help text, or version was printed.
 90	  1  An operational error prevented a decision.
 91	  2  Invalid command-line usage.`;
 92	}
 93	
 94	function usageError(message: string): CliUsageError {
 95	  return new CliUsageError(`${message}\n\n${usage()}`);
 96	}
 97	
 98	function taskFromPositionals(positionals: string[]): string {
 99	  try {
100	    return requireBoundedTask(positionals.slice(1).join(' ').trim());
101	  } catch (error) {
102	    throw usageError(error instanceof Error ? error.message : String(error));
103	  }
104	}
105	
106	function withoutNodeArgumentSeparator(argv: string[]): string[] {
107	  return argv[0] === '--' ? argv.slice(1) : argv;
108	}
109	
110	export function parseArgs(argv: string[]): CliCommand {
111	  let mock = false;
112	  let noTrace = false;
113	  let json = false;
114	  let showHelp = false;
115	  let showVersion = false;
116	  let parseFlags = true;
117	  const positional: string[] = [];
118	
119	  for (const arg of withoutNodeArgumentSeparator(argv)) {
120	    if (!parseFlags) {
121	      positional.push(arg);
122	      continue;
123	    }
124	
125	    if (arg === '--') {
126	      parseFlags = false;
127	      continue;
128	    }
129	
130	    switch (arg) {
131	      case '--mock':
132	        mock = true;
133	        break;
134	      case '--no-trace':
135	        noTrace = true;
136	        break;
137	      case '--json':
138	        json = true;
139	        break;
140	      case '--help':
141	      case '-h':
142	        showHelp = true;
143	        break;
144	      case '--version':
145	        showVersion = true;
146	        break;
147	      default:
148	        if (arg.startsWith('-')) {
149	          throw usageError(`Unknown option: ${arg}`);
150	        }
151	        positional.push(arg);
152	    }
153	  }
154	
155	  if (showHelp || showVersion) {
156	    if (showHelp && showVersion) {
157	      throw usageError('Use either --help or --version, not both.');
158	    }
159	    if (mock || noTrace || json || positional.length > 0) {
160	      throw usageError('--help and --version cannot be combined with a decision request.');
161	    }
162	    return showHelp ? { kind: 'help' } : { kind: 'version' };
163	  }
164	
165	  if (positional.length < 2) {
166	    throw usageError('Missing repository path or task.');
167	  }
168	
169	  const repoPath = positional[0] ?? '';
170	  const task = taskFromPositionals(positional);
171	  return {
172	    kind: 'run',
173	    options: { repoPath, task, mock, noTrace, json },
174	  };
175	}
176	
177	function percent(value: number): string {
178	  return `${Math.round(value * 100)}%`;
179	}
180	
181	function printDistribution(probabilities: Partial<Record<Action, number>>): void {
182	  const entries = Object.entries(probabilities).sort(([, a], [, b]) => (b ?? 0) - (a ?? 0));
183	  for (const [action, probability] of entries) {
184	    console.log(`  ${action.padEnd(14)} ${percent(probability ?? 0).padStart(4)}`);
185	  }
186	}
187	
188	function makeState(repo: RepoSnapshot, task: string): AgentState {
189	  return {
190	    task,
191	    iteration: 1,
192	    currentGoal: 'Choose the safest useful first action.',
193	    repo,
194	    filesRead: [],
195	    filesModified: [],
196	    observations: ['Initial repository snapshot collected.'],
197	    commandsRun: [],
198	    tests: { ran: false },
199	    failedApproaches: [],
200	    codexCalls: 0,
201	  };
202	}
203	
204	export function createDecisionOutput(
205	  state: AgentState,
206	  evaluation: EvaluationResult,
207	  policy: PolicyDecision,
208	  mode: DecisionOutput['mode'],
209	  tracePath?: string,
210	): DecisionOutput {
211	  return {
212	    schemaVersion: 1,
213	    status: 'unexecuted',
214	    mode,
215	    repo: state.repo,
216	    task: state.task,
217	    assessment: evaluation.assessment,
218	    policy,
219	    model: evaluation.model,
220	    latencyMs: evaluation.latencyMs,
221	    ...(tracePath === undefined ? {} : { tracePath }),
222	  };
223	}
224	
225	export async function runDecision(
226	  options: Omit<CliOptions, 'json'>,
227	  cwd: string = process.cwd(),
228	): Promise<DecisionOutput> {
229	  const repo = await inspectRepo(options.repoPath);
230	  const state = makeState(repo, options.task);
231	  const mode: DecisionOutput['mode'] = options.mock ? 'mock' : 'live';
232	
233	  if (!options.mock) requireGatewayApiKey();
234	  const evaluation = options.mock ? mockEvaluation() : await evaluateAgentState(state);
235	  const policy = applyPolicy(state, evaluation.assessment);
236	  const tracePath = options.noTrace
237	    ? undefined
238	    : path.relative(cwd, await writeTrace(cwd, { state, evaluation, policy }));
239	
240	  return createDecisionOutput(state, evaluation, policy, mode, tracePath);
241	}
242	
243	function printHumanDecision(decision: DecisionOutput): void {
244	  const { assessment, policy } = decision;
245	  console.log('\nJev Orchestrator — decision-only milestone');
246	  console.log('Status: unexecuted decision (no tools or coding agents ran)\n');
247	  console.log(`Repo: ${decision.repo.root}`);
248	  console.log(`Task: ${decision.task}`);
249	  console.log(`Mode: ${decision.mode === 'mock' ? 'mock' : 'live Jev'}\n`);
250	  console.log(`Task complete       ${percent(assessment.taskComplete.probability)}`);
251	  console.log(`Needs information  ${percent(assessment.needsMoreInformation.probability)}`);
252	  console.log(`Needs testing      ${percent(assessment.needsTesting.probability)}`);
253	  console.log(`Stuck              ${percent(assessment.stuck.probability)}\n`);
254	  console.log('Next-action distribution');
255	  printDistribution(assessment.nextAction.probabilities);
256	  console.log(`\nJev requested: ${policy.requested}`);
257	  console.log(`Policy selected (unexecuted): ${policy.selected}${policy.override ? ' (override)' : ''}`);
258	  console.log(`Reason: ${policy.reason}`);
259	  console.log(`Latency: ${decision.latencyMs}ms`);
260	  if (decision.tracePath !== undefined) console.log(`Trace: ${decision.tracePath}`);
261	}
262	
263	async function packageVersion(): Promise<string> {
264	  const manifest = await readFile(new URL('../package.json', import.meta.url), 'utf8');
265	  const parsed: unknown = JSON.parse(manifest);
266	  if (
267	    typeof parsed !== 'object' ||
268	    parsed === null ||
269	    !('version' in parsed) ||
270	    typeof parsed.version !== 'string'
271	  ) {
272	    throw new Error('Unable to read the package version.');
273	  }
274	  return parsed.version;
275	}
276	
277	export function exitCodeFor(error: unknown): number {
278	  return error instanceof CliUsageError
279	    ? EXIT_CODES.usageError
280	    : EXIT_CODES.operationalError;
281	}
282	
283	function errorOutput(error: unknown): ErrorOutput {
284	  const usage = error instanceof CliUsageError;
285	  return {
286	    schemaVersion: 1,
287	    status: 'error',
288	    error: {
289	      kind: usage ? 'usage' : 'operational',
290	      message: error instanceof Error ? error.message : String(error),
291	    },
292	    exitCode: exitCodeFor(error),
293	  };
294	}
295	
296	function wantsJsonError(argv: string[]): boolean {
297	  let parseFlags = true;
298	  for (const arg of withoutNodeArgumentSeparator(argv)) {
299	    if (!parseFlags) continue;
300	    if (arg === '--') {
301	      parseFlags = false;
302	      continue;
303	    }
304	    if (arg === '--json') return true;
305	  }
306	  return false;
307	}
308	
309	export async function main(argv: string[] = process.argv.slice(2)): Promise<void> {
310	  const command = parseArgs(argv);
311	  if (command.kind === 'help') {
312	    console.log(usage());
313	    return;
314	  }
315	  if (command.kind === 'version') {
316	    console.log(await packageVersion());
317	    return;
318	  }
319	
320	  const decision = await runDecision(command.options);
321	  if (command.options.json) {
322	    console.log(JSON.stringify(decision));
323	    return;
324	  }
325	  printHumanDecision(decision);
326	}
327	
328	function isDirectInvocation(): boolean {
329	  const entryPoint = process.argv[1];
330	  return entryPoint !== undefined && import.meta.url === pathToFileURL(path.resolve(entryPoint)).href;
331	}
332	
333	if (isDirectInvocation()) {
334	  void main().catch((error: unknown) => {
335	    if (wantsJsonError(process.argv.slice(2))) {
336	      console.error(JSON.stringify(errorOutput(error)));
337	    } else {
338	      console.error(`\nError: ${error instanceof Error ? error.message : String(error)}`);
339	    }
340	    process.exitCode = exitCodeFor(error);
341	  });
342	}

