  1	import { lstat, open, opendir, stat } from 'node:fs/promises';
  2	import path from 'node:path';
  3	import { spawn } from 'node:child_process';
  4	import type { RepoSnapshot } from '../types.js';
  5	import { truncateText } from '../limits.js';
  6	
  7	export const MAX_PACKAGE_JSON_BYTES = 64 * 1024;
  8	export const MAX_TOP_LEVEL_FILES = 80;
  9	export const MAX_TOP_LEVEL_ENTRIES_SCANNED = 256;
 10	export const MAX_SCRIPTS = 100;
 11	export const MAX_GIT_OUTPUT_BYTES = 32 * 1024;
 12	export const MAX_GIT_STATUS_ENTRIES = 100;
 13	export const GIT_TIMEOUT_MS = 2_000;
 14	
 15	const MAX_PACKAGE_NAME_LENGTH = 200;
 16	const MAX_SCRIPT_NAME_LENGTH = 200;
 17	const MAX_GIT_LINE_LENGTH = 500;
 18	
 19	type PackageMetadata = {
 20	  packageName?: string;
 21	  scripts: string[];
 22	};
 23	
 24	function isRecord(value: unknown): value is Record<string, unknown> {
 25	  return value !== null && typeof value === 'object' && !Array.isArray(value);
 26	}
 27	
 28	async function isRegularFile(file: string): Promise<boolean> {
 29	  try {
 30	    return (await lstat(file)).isFile();
 31	  } catch {
 32	    return false;
 33	  }
 34	}
 35	
 36	async function git(root: string, args: string[]): Promise<string> {
 37	  return new Promise((resolve) => {
 38	    const child = spawn('git', ['-c', 'core.fsmonitor=false', ...args], {
 39	      cwd: root,
 40	      stdio: ['ignore', 'pipe', 'ignore'],
 41	      env: {
 42	        ...process.env,
 43	        GIT_OPTIONAL_LOCKS: '0',
 44	        GIT_TERMINAL_PROMPT: '0',
 45	      },
 46	    });
 47	    let output = '';
 48	    let outputBytes = 0;
 49	    let interrupted = false;
 50	    let settled = false;
 51	    const timeout = setTimeout(() => {
 52	      interrupted = true;
 53	      child.kill();
 54	    }, GIT_TIMEOUT_MS);
 55	    timeout.unref();
 56	
 57	    const finish = (value: string): void => {
 58	      if (settled) return;
 59	      settled = true;
 60	      clearTimeout(timeout);
 61	      resolve(value);
 62	    };
 63	
 64	    child.stdout.on('data', (chunk: Buffer) => {
 65	      if (interrupted) return;
 66	
 67	      const availableBytes = MAX_GIT_OUTPUT_BYTES - outputBytes;
 68	      if (availableBytes <= 0 || chunk.length > availableBytes) {
 69	        interrupted = true;
 70	        child.kill();
 71	        return;
 72	      }
 73	
 74	      output += chunk.toString('utf8');
 75	      outputBytes += chunk.length;
 76	    });
 77	    child.on('error', () => finish(''));
 78	    child.on('close', (code) => finish(code === 0 && !interrupted ? output.trim() : ''));
 79	  });
 80	}
 81	
 82	async function readTopLevelFiles(root: string): Promise<string[]> {
 83	  const directory = await opendir(root);
 84	  const entries: string[] = [];
 85	  let scanned = 0;
 86	
 87	  for await (const entry of directory) {
 88	    scanned += 1;
 89	    if (entry.name !== 'node_modules' && entry.name !== '.git') {
 90	      entries.push(`${entry.name}${entry.isDirectory() ? '/' : ''}`);
 91	    }
 92	    if (scanned >= MAX_TOP_LEVEL_ENTRIES_SCANNED) break;
 93	  }
 94	
 95	  return entries.sort().slice(0, MAX_TOP_LEVEL_FILES);
 96	}
 97	
 98	async function readPackageMetadata(packageJsonPath: string): Promise<PackageMetadata> {
 99	  if (!(await isRegularFile(packageJsonPath))) return { scripts: [] };
100	
101	  try {
102	    const packageJson = await open(packageJsonPath, 'r');
103	    try {
104	      const contents = Buffer.alloc(MAX_PACKAGE_JSON_BYTES + 1);
105	      const { bytesRead } = await packageJson.read(contents, 0, contents.length, 0);
106	      if (bytesRead > MAX_PACKAGE_JSON_BYTES) return { scripts: [] };
107	
108	      const parsed: unknown = JSON.parse(contents.subarray(0, bytesRead).toString('utf8'));
109	      if (!isRecord(parsed)) return { scripts: [] };
110	
111	      const packageName = typeof parsed.name === 'string'
112	        ? truncateText(parsed.name, MAX_PACKAGE_NAME_LENGTH)
113	        : undefined;
114	      const scripts = isRecord(parsed.scripts)
115	        ? Object.entries(parsed.scripts)
116	          .filter(([, value]) => typeof value === 'string')
117	          .map(([name]) => truncateText(name, MAX_SCRIPT_NAME_LENGTH))
118	          .sort()
119	          .slice(0, MAX_SCRIPTS)
120	        : [];
121	
122	      return { ...(packageName ? { packageName } : {}), scripts };
123	    } finally {
124	      await packageJson.close();
125	    }
126	  } catch {
127	    return { scripts: [] };
128	  }
129	}
130	
131	async function detectPackageManager(root: string): Promise<RepoSnapshot['packageManager']> {
132	  if (await isRegularFile(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
133	  if (await isRegularFile(path.join(root, 'package-lock.json'))) return 'npm';
134	  if (await isRegularFile(path.join(root, 'yarn.lock'))) return 'yarn';
135	  if (
136	    (await isRegularFile(path.join(root, 'bun.lock'))) ||
137	    (await isRegularFile(path.join(root, 'bun.lockb')))
138	  ) {
139	    return 'bun';
140	  }
141	  return 'unknown';
142	}
143	
144	async function inspectGit(root: string): Promise<Pick<RepoSnapshot, 'gitBranch' | 'gitStatus'>> {
145	  const gitRoot = await git(root, ['rev-parse', '--show-toplevel']);
146	  if (!gitRoot || path.resolve(gitRoot) !== root) return { gitStatus: [] };
147	
148	  const [gitBranch, status] = await Promise.all([
149	    git(root, ['branch', '--show-current']),
150	    git(root, ['status', '--short', '--no-renames', '--untracked-files=normal']),
151	  ]);
152	
153	  return {
154	    ...(gitBranch ? { gitBranch: truncateText(gitBranch, MAX_GIT_LINE_LENGTH) } : {}),
155	    gitStatus: status
156	      ? status
157	        .split('\n')
158	        .slice(0, MAX_GIT_STATUS_ENTRIES)
159	        .map((line) => truncateText(line, MAX_GIT_LINE_LENGTH))
160	      : [],
161	  };
162	}
163	
164	export async function inspectRepo(inputPath: string): Promise<RepoSnapshot> {
165	  const root = path.resolve(inputPath);
166	  let rootStat;
167	  try {
168	    rootStat = await stat(root);
169	  } catch {
170	    throw new Error(`Repository path does not exist: ${root}`);
171	  }
172	  if (!rootStat.isDirectory()) throw new Error(`Repository path must be a directory: ${root}`);
173	
174	  const packageJsonPath = path.join(root, 'package.json');
175	  const [topLevelFiles, packageMetadata, packageManager, gitMetadata] = await Promise.all([
176	    readTopLevelFiles(root),
177	    readPackageMetadata(packageJsonPath),
178	    detectPackageManager(root),
179	    inspectGit(root),
180	  ]);
181	
182	  const validationNames = new Set(['test', 'check', 'typecheck', 'lint', 'build']);
183	  const validationScripts = packageMetadata.scripts.filter((script) =>
184	    [...validationNames].some((name) => script === name || script.startsWith(`${name}:`)),
185	  );
186	
187	  return {
188	    root,
189	    packageManager,
190	    ...(packageMetadata.packageName ? { packageName: packageMetadata.packageName } : {}),
191	    scripts: packageMetadata.scripts,
192	    validationScripts,
193	    ...gitMetadata,
194	    topLevelFiles,
195	  };
196	}
