 65	function redactText(value: string, secretValues: string[]): string {
 66	  let redacted = value;
 67	  for (const secret of secretValues) {
 68	    redacted = redacted.replaceAll(secret, REDACTED);
 69	  }
 70	  return redacted
 71	    .replace(KEY_VALUE_SECRET, `$1${REDACTED}`)
